// Empty Base Optimization (EBO)
struct [[no_unique_address]] ZeroByte {};

// EBO utilizes the fact that a base class
// with size zero needs no separate storage.
class OptimizedStore : private ZeroByte {
    int value;
};

// Size calculation relies on EBO:
// sizeof(OptimizedStore) == sizeof(int)
// (Typically 4 bytes, saving the 1 byte ZeroByte needed if held as a member)

// Standard C++20 Attribute for members:
struct Container {
    [[no_unique_address]] ZeroByte z;
    int value;
};

// sizeof(Container) == sizeof(int)
// (Compiler handles non-overlapping addresses)
